// Path-scoped skills: a pack's `skillsBeforeEditing` declarations, resolved
// against the packs a repo activates, and the one question both readers ask of
// them — which declared skills does THIS path need that the session has not yet
// loaded. The PreToolUse hook (engine/hooks/pretooluse-command.mjs) asks it before
// a file tool runs, so the skill is loaded before the first edit exists; the
// `skill-loaded-before-editing` work rule asks it of the diff at Stop, which is
// what catches an edit the hook never saw (one made through Bash). One resolver,
// so the two cannot disagree about a pattern.
//
// Pattern grammar is the gitignore subset a reader already knows: `**` spans
// directories, `*` and `?` stay inside one segment, everything else is literal.
// A pattern is matched against the whole repo-relative path, so `product-wiki/**`
// is the tree and `**/packs/*/RULES.md` is that file at any depth.

const RE_SPECIALS = /[.+^${}()|[\]\\]/g;

export function globToRegExp(glob) {
  let re = '';
  for (let i = 0; i < glob.length; i += 1) {
    const c = glob[i];
    if (c === '*' && glob[i + 1] === '*') {
      // `**/` — zero or more whole segments; a trailing `**` — anything at all.
      if (glob[i + 2] === '/') { re += '(?:.*/)?'; i += 2; } else { re += '.*'; i += 1; }
    } else if (c === '*') re += '[^/]*';
    else if (c === '?') re += '[^/]';
    else re += c.replace(RE_SPECIALS, '\\$&');
  }
  return new RegExp(`^${re}$`);
}

// The declarations of the given packs, flattened: [{ pack, files, skill, re }].
// Callers pass the ACTIVE packs — activation is the registry's call, not this
// module's — so an undeclared pack's patterns never bind anything.
export function pathScopedSkills(packs) {
  const out = [];
  for (const pack of packs ?? []) {
    for (const d of pack.skillsBeforeEditing ?? []) {
      out.push({ pack: pack.id, files: d.files, skill: d.skill, re: globToRegExp(d.files) });
    }
  }
  return out;
}

// The declarations `path` matches whose skill is not among `loaded`, deduped by
// skill name — the reason to stop an edit, or the empty list that lets it run.
export function missingSkillsFor(path, declarations, loaded) {
  const have = new Set(loaded ?? []);
  const seen = new Set();
  const missing = [];
  for (const d of declarations) {
    if (!d.re.test(path) || have.has(d.skill) || seen.has(d.skill)) continue;
    seen.add(d.skill);
    missing.push(d);
  }
  return missing;
}
