  }
  if (payload.tool_name !== 'Bash') process.exit(0);
  const cmd = payload.tool_input?.command ?? '';
  const deletesRemoteBranch =
    /\bgit\s+push\b[^\n;&]*\s(--delete|-d)\s/.test(cmd) ||
    /\bgit\s+push\b[^\n;&]*\s\S+\s+:\S/.test(cmd);
