// A skill's own declaration: the YAML frontmatter at the top of its SKILL.md, read
// for the three fields the corpus acts on — `name`, `description` (what the harness
// matches a session's activity against) and `paths` (the files the skill is scoped
// to, the harness's own field: it activates the skill only when Claude works with a
// matching file, and the PreToolUse guard holds a file tool aimed there until the
// skill is loaded). The rest of the frontmatter is the harness's business.
//
// A deliberate subset of YAML, never a general parser: `key: scalar`, a block list
// under a key (`- item`), quoted or bare scalars, and a comma-separated scalar where
// the harness accepts one (`paths`). Anything else is left unread, and a file with no
// frontmatter — or a malformed one — reads as a skill with empty metadata, which is
// exactly what the harness does with it (skills docs, "malformed frontmatter").
import { readFileSync } from 'node:fs';
import { join } from 'node:path';

const unquote = (s) => {
  const t = s.trim();
  return (t.length >= 2 && ((t[0] === '"' && t.at(-1) === '"') || (t[0] === "'" && t.at(-1) === "'")))
    ? t.slice(1, -1) : t;
};

export function parseFrontmatter(text) {
  const out = {};
  if (!text.startsWith('---')) return out;
  const end = text.indexOf('\n---', 3);
  if (end === -1) return out;
  const lines = text.slice(text.indexOf('\n') + 1, end).split('\n');
  let listKey = null;
  for (const line of lines) {
    const item = /^\s+-\s*(.*)$/.exec(line);
    if (item && listKey) { out[listKey].push(unquote(item[1])); continue; }
    const kv = /^([A-Za-z_][\w-]*):\s*(.*)$/.exec(line);
    if (!kv) continue;
    const [, key, rest] = kv;
    if (rest.trim() === '') { out[key] = []; listKey = key; continue; }
    listKey = null;
    const flow = /^\[(.*)\]$/.exec(rest.trim());
    out[key] = flow ? flow[1].split(',').map(unquote).filter(Boolean) : unquote(rest);
  }
  return out;
}

// The `paths` field as a list whatever its spelling — a block list, a flow list, or
// one comma-separated string, all of which the harness accepts.
export const pathsOf = (fm) => (Array.isArray(fm.paths)
  ? fm.paths
  : typeof fm.paths === 'string' ? fm.paths.split(',').map((s) => s.trim()).filter(Boolean) : []);

// The metadata of the skill at `dir`: { name, description, paths }. Unreadable is
// empty metadata, on the harness's own terms.
export function skillMetadata(dir) {
  let fm = {};
  try { fm = parseFrontmatter(readFileSync(join(dir, 'SKILL.md'), 'utf8')); } catch { /* no SKILL.md */ }
  return {
    name: typeof fm.name === 'string' ? fm.name : '',
    description: typeof fm.description === 'string' ? fm.description : '',
    paths: pathsOf(fm),
  };
}
EOF
cat > engine/checks/helpers/path-scoped-skills.mjs <<'EOF'
// Path-scoped skills: every skill an active pack bundles that carries a `paths:`
// frontmatter (the harness's own field — it activates the skill only when Claude
// works with a matching file), and the one question both readers ask of them —
// which of those skills does THIS path need that the session has not yet loaded.
// The PreToolUse hook (engine/hooks/pretooluse-command.mjs) asks it before a file
// tool runs, so the skill is loaded before the first edit exists; the
// `skill-loaded-before-editing` work rule asks it of the diff at Stop, which is what
// catches an edit the hook never saw (one made through Bash). One resolver, so the
// two cannot disagree about a pattern.
//
// Pattern grammar is the harness's (memory docs, "path-specific rules"): `**` spans
// directories, `*` and `?` stay inside one segment, `{a,b}` expands, everything
// else is literal, and a pattern is matched against the whole repo-relative path —
// so `wiki/**` is the tree and `**/packs/*/RULES.md` is that file at any depth.
import { join } from 'node:path';
import { skillMetadata } from '../../pack_loader/skill-frontmatter.mjs';

const RE_SPECIALS = /[.+^${}()|[\]\\]/g;

// `{a,b}` groups multiplied out, innermost first, so the matcher below never sees one.
export function expandBraces(glob) {
  const m = /\{([^{}]*)\}/.exec(glob);
  if (!m) return [glob];
  return m[1].split(',').flatMap((alt) => expandBraces(glob.slice(0, m.index) + alt + glob.slice(m.index + m[0].length)));
}

function oneGlobToSource(glob) {
  let re = '';
  for (let i = 0; i < glob.length; i += 1) {
    const c = glob[i];
    if (c === '*' && glob[i + 1] === '*') {
      // `**/` — zero or more whole segments; a trailing `**` — anything at all.
      if (glob[i + 2] === '/') { re += '(?:.*/)?'; i += 2; } else { re += '.*'; i += 1; }
    } else if (c === '*') re += '[^/]*';
    else if (c === '?') re += '[^/]';
    else re += c.replace(RE_SPECIALS, '\\$&');
  }
  return re;
}

export function globToRegExp(glob) {
  return new RegExp(`^(?:${expandBraces(glob).map(oneGlobToSource).join('|')})$`);
}

// The scoped skills of the given packs, flattened: [{ pack, skill, files, re }], one
// entry per pattern. Callers pass the ACTIVE packs — activation is the registry's
// call, not this module's — so an undeclared pack's skills bind nothing. Read off each
// pack's own `skills` list (the convention fills it from the directory), so a skill the
// manifest withholds is not scoped either.
export function pathScopedSkills(packs) {
  const out = [];
  for (const pack of packs ?? []) {
    if (!pack.dir) continue;
    for (const skill of pack.skills ?? []) {
      for (const files of skillMetadata(join(pack.dir, 'skills', skill)).paths) {
        out.push({ pack: pack.id, skill, files, re: globToRegExp(files) });
      }
    }
  }
  return out;
}

// The declarations `path` matches whose skill is not among `loaded`, deduped by
// skill name — the reason to stop an edit, or the empty list that lets it run.
export function missingSkillsFor(path, declarations, loaded) {
  const have = new Set(loaded ?? []);
  const seen = new Set();
  const missing = [];
  for (const d of declarations) {
    if (!d.re.test(path) || have.has(d.skill) || seen.has(d.skill)) continue;
    seen.add(d.skill);
    missing.push(d);
  }
  return missing;
}
