# the skills themselves
def scope(p, globs):
    def f(s):
        head, rest = s.split('\n---\n',1)
        assert '\npaths:' in head, p
        head = re.sub(r'\npaths:\n(?:  - .*\n?)+', '\n', head + '\n').rstrip('\n')
        block = '\nmetadata:\n  ' + KEY + ':\n' + ''.join(f'    - "{g}"\n' for g in globs)
        return head + block + '---\n' + rest
    rw(p,f)
